async function loadAdminStats(){if(!db||!isAdmin)return;const [stats,users,farmsResult]=await Promise.all([db.rpc('platform_stats'),db.rpc('admin_list_users'),db.rpc('admin_list_farms')]);if(stats.error)error(stats.error);else setAdminStats(stats.data);if(users.error)error(users.error);else setAdminUsers(users.data??[]);if(farmsResult.error)error(farmsResult.error);else setAdminFarms(farmsResult.data??[]);const loc=await db.rpc('admin_list_farm_locations');if(loc.error)setMapNotice('Standorte konnten nicht geladen werden: '+loc.error.message);else{setFarmLocations(loc.data??[]);setMapNotice('')}}
 async function locateFarms(){
  if(!isAdmin||mapBusy)return;
  setMapBusy(true);setMapNotice('Standorte werden ermittelt. Adressen werden dafür an OpenStreetMap Nominatim übertragen.');
  const points:MapPoint[]=[];let missing=0;
  try{
   for(const f of farmLocations){
    if(!f.street_address||!f.postal_code||!f.city){missing++;continue;}
    const address=[f.street_address,f.postal_code,f.city,'Deutschland'].join(', ');
    const cacheKey='calfmanager-geocode-v1:'+f.id;
    let cached:{address:string;lat:number;lon:number}|null=null;
    try{cached=JSON.parse(localStorage.getItem(cacheKey)||'null')}catch{/* kein Cache */}
    if(cached?.address===address&&Number.isFinite(cached.lat)&&Number.isFinite(cached.lon)){
      points.push({...f,lat:cached.lat,lon:cached.lon});continue;
    }
    // Maximal eine Anfrage pro Sekunde; ausschließlich nach explizitem Admin-Klick.
    const params=new URLSearchParams({q:address,format:'json',limit:'1',countrycodes:'de'});
    const response=await fetch('https://nominatim.openstreetmap.org/search?'+params.toString(),{headers:{Accept:'application/json'}});
    if(!response.ok)throw new Error('Geocodierung vorübergehend nicht verfügbar ('+response.status+').');
    const matches=await response.json() as Array<{lat:string;lon:string}>;
    const lat=Number(matches[0]?.lat),lon=Number(matches[0]?.lon);
    if(matches.length&&Number.isFinite(lat)&&Number.isFinite(lon)){
      points.push({...f,lat,lon});
      try{localStorage.setItem(cacheKey,JSON.stringify({address,lat,lon}))}catch{/* Speicher optional */}
    }else missing++;
    setMapPoints([...points]);
    await new Promise(resolve=>setTimeout(resolve,1100));
   }
   setMapPoints(points);
   setMapNotice(`${points.length} Standorte angezeigt${missing?`; ${missing} ohne gültige Position`:''}. Die ermittelten Koordinaten werden in diesem Browser zwischengespeichert.`);
  }catch(e){setMapNotice(e instanceof Error?e.message:String(e));setMapPoints(points)}
  finally{setMapBusy(false)}
 }
